    public static void testNumericClassificationIsPinnedToRecordedRecordedCasesAndReviewedDifferences() {
        emon.Port.Cells c = emon.Port.newCells();
        int at = 0;
        int row = 0;
        int differences = 0;
        while (at < 8179) {
            int recorded = ON_CASES[at];
            int expected = ON_CASES[at + 1];
            int n = ON_CASES[at + 2];
            int i = 0;
            int cp = 0;
            int latin = 0;
            emon.Port.cellsDrop(c, 0);
            int answer = Oil.oilBegin(c, 12, 1, 256, 256, 1, 1, 0, 0);
            int word = Oil.oilWord(c, answer, 0, 0, 1, 1, -1, 500, 0, 0, -1, 0);
            while (i < n) {
                cp = ON_CASES[(at + 3) + i];
                Oil.oilWordCp(c, answer, word, cp);
                if (((cp >= 65) && (cp <= 90)) || ((cp >= 97) && (cp <= 122))) {
                    latin += 1;
                }
                i += 1;
            }
            Oil.oilEnd(c, answer);
            emon.Testport.assertEqAt(Oil.oilWordFlags(c, answer, word) & 2, expected, "recorded numeric classification or reviewed difference", row);
            if (recorded != expected) {
                emon.Testport.assertThat(latin < 3, "a numeric difference cannot change the dictionary penalty");
                differences += 1;
            }
            at = (at + 3) + n;
            row += 1;
        }
        emon.Testport.assertEq(row, 952, "all captured numeric candidates");
        emon.Testport.assertEq(differences, 81, "all deliberate differences are accounted for");
    }
